    const row = numbers[0];
    const col = numbers[1];

    const diag = row + col - 1;
    const index = ((diag - 1) * diag) / 2 + (col - 1);

    const start: u64 = 20151125;
    const mult: u64 = 252533;
    const modv: u64 = 33554393;

    const code = (start * modPow(mult, index, modv)) % modv;
