### Step 1: Enable Flakes

Edit `/etc/nix/nix.conf` and add:

```
experimental-features = nix-command flakes
```

---

### Step 2: Prepare Flake Directory

```sh
sudo mkdir -p /etc/nixos
cd /etc/nixos
sudo git init
```

---

### Step 3: Create Flake Files

#### `/etc/nixos/flake.nix`

```nix
{
  description = "NixOS config with flakes and Home Manager";

  inputs = {
    nixpkgs.url = "github:NixOS/nixpkgs/nixos-unstable";
    home-manager.url = "github:nix-community/home-manager";
    flake-utils.url = "github:numtide/flake-utils";
  };

  outputs = { self, nixpkgs, home-manager, flake-utils, ... }:
    flake-utils.lib.eachDefaultSystem (system:
      let
        pkgs = import nixpkgs {
          inherit system;
          config.allowUnfree = true;
        };
        username = "alice"; # change to your user
        hostname = "nixos"; # change to your hostname
      in {
        nixosConfigurations.${hostname} = nixpkgs.lib.nixosSystem {
          system = system;
          modules = [
            ./configuration.nix
            home-manager.nixosModules.home-manager
            {
              home-manager.useGlobalPkgs = true;
              home-manager.useUserPackages = true;
              home-manager.users.${username} = import ./home.nix;
            }
          ];
        };
      }
    );
}
```

#### `/etc/nixos/configuration.nix`

```nix
{ config, pkgs, ... }:

{
  networking.hostName = "nixos"; # change as needed
  time.timeZone = "UTC";
  i18n.defaultLocale = "en_US.UTF-8";

  users.users.alice = {
    isNormalUser = true;
    extraGroups = [ "wheel" "networkmanager" ];
    shell = pkgs.zsh;
  };

  services.xserver.enable = true;
  services.xserver.displayManager.gdm.enable = true;
  services.xserver.desktopManager.gnome.enable = true;
  services.xserver.displayManager.gdm.wayland = true;

  services.networkmanager.enable = true;

  environment.systemPackages = with pkgs; [
    curl git htop wget unzip tree tmux gcc make zip
    neovim
    vscode
    brave
    bitwarden
    # zed may not be in nixpkgs; see below
  ];

  system.stateVersion = "23.11"; # adjust to your NixOS version
}
```

#### `/etc/nixos/home.nix`

```nix
{ config, pkgs, ... }:

{
  home.username = "alice";
  home.homeDirectory = "/home/alice";

  programs.neovim.enable = true;
  programs.zsh.enable = true;

  # If zed is not in nixpkgs, you can add it via home.packages as a manual derivation or overlay.
  # For now, just add a placeholder:
  home.packages = [
    # (custom zed derivation here if needed)
  ];

  # Add any user-specific settings here
}
```

