                        } else {
                            match.addPoint(player: "Player 2")
                        }
                    }
                    if advanced {
                        Picker("Detail", selection: $selectedDetailP2) {
                            ForEach(PointDetail.allCases) { d in
                                Text(d.rawValue).tag(d)
                            }
                        }
                        .pickerStyle(MenuPickerStyle())
                    }
                }
            }
            Toggle("Advanced", isOn: $advanced)
            if advanced {
                List(match.points.reversed()) { point in
                    VStack(alignment: .leading) {
                        Text("\(point.player): \(point.detail?.rawValue ?? "Point")")
                        Text(point.timestamp, style: .time).font(.caption)
                    }
                }
            }
            Button("Reset") { match.reset() }
        }
        .padding()
    }
}

@main
