<body>
  <div class="toolbar">
    <button id="openBtn">Open</button>
    <button id="saveBtn">Save</button>
    <button id="undoBtn">Undo</button>
    <button id="redoBtn">Redo</button>
    <label>Lang:
      <select id="langSel">
        <option value="js">JS</option>
        <option value="html">HTML</option>
        <option value="css">CSS</option>
        <option value="plain">Plain</option>
      </select>
    </label>
    <label>Font size:
      <input type="range" id="fontSize" min="10" max="28" value="16">
    </label>
    <button id="themeBtn">Toggle Theme</button>
    <button id="findBtn">Find/Replace</button>
    <input type="file" id="fileInput" style="display:none" accept=".txt,.js,.html,.css">
  </div>
  <div class="findbar" id="findBar" style="display:none;">
    <input id="findInput" placeholder="Find">
    <input id="replaceInput" placeholder="Replace">
    <label><input type="checkbox" id="regexChk">Regex</label>
    <button id="findNextBtn">Next</button>
    <button id="findPrevBtn">Prev</button>
    <button id="replaceBtn">Replace</button>
    <button id="replaceAllBtn">Replace All</button>
    <button id="closeFindBtn">Close</button>
  </div>
  <div id="container">
    <div id="lineNumbers">1</div>
    <div id="editorWrap">
      <pre id="highlight"></pre>
      <textarea id="editor" spellcheck="false"></textarea>
    </div>
  </div>
  <div id="status">
    <span id="cursorPos">Ln 1, Col 1</span>
    <span id="wordCount">Words: 0 | Chars: 0</span>
  </div>
  <script>
    // Elements
    const editor = document.getElementById('editor');
    const highlight = document.getElementById('highlight');
    const lineNumbers = document.getElementById('lineNumbers');
    const langSel = document.getElementById('langSel');
    const fontSize = document.getElementById('fontSize');
    const themeBtn = document.getElementById('themeBtn');
    const status = document.getElementById('status');
    const cursorPos = document.getElementById('cursorPos');
    const wordCount = document.getElementById('wordCount');
    const openBtn = document.getElementById('openBtn');
    const saveBtn = document.getElementById('saveBtn');
    const fileInput = document.getElementById('fileInput');
    const undoBtn = document.getElementById('undoBtn');
    const redoBtn = document.getElementById('redoBtn');
    const findBtn = document.getElementById('findBtn');
    const findBar = document.getElementById('findBar');
    const findInput = document.getElementById('findInput');
    const replaceInput = document.getElementById('replaceInput');
    const regexChk = document.getElementById('regexChk');
    const findNextBtn = document.getElementById('findNextBtn');
    const findPrevBtn = document.getElementById('findPrevBtn');
    const replaceBtn = document.getElementById('replaceBtn');
    const replaceAllBtn = document.getElementById('replaceAllBtn');
    const closeFindBtn = document.getElementById('closeFindBtn');

    // State
    let theme = localStorage.getItem('notepad-theme') || 'dark';
    let lang = localStorage.getItem('notepad-lang') || 'js';
    let findMatches = [];
    let findIndex = 0;

    // Syntax highlighting
    function escapeHtml(str) {
      return str.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;");
    }
    function highlightCode(code, lang) {
      code = escapeHtml(code);
      if(lang === 'plain') return code;
      if(lang === 'js') {
        code = code.replace(/(\/\/.*|\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/(["'`])(?:\\.|(?!\1).)*\1/g, '<span class="token string">$&</span>');
        code = code.replace(/\b(function|return|var|let|const|if|else|for|while|break|continue|switch|case|default|throw|try|catch|finally|new|this|typeof|instanceof|in|of|do|await|async|class|extends|super|import|from|export)\b/g, '<span class="token keyword">$1</span>');
        code = code.replace(/\b\d+(\.\d+)?\b/g, '<span class="token number">$&</span>');
        code = code.replace(/\b(true|false|null|undefined|NaN)\b/g, '<span class="token keyword">$&</span>');
        code = code.replace(/([{}[\];(),.:])/g, '<span class="token punctuation">$1</span>');
      } else if(lang === 'html') {
        code = code.replace(/(&lt;!--[\s\S]*?--&gt;)/g, '<span class="token comment">$1</span>');
        code = code.replace(/(&lt;\/?[a-zA-Z0-9\-]+)([^&]*?)(&gt;)/g, function(m,p1,p2,p3){
          p2 = p2.replace(/([a-zA-Z\-:]+)(=)("[^"]*"|'[^']*')/g, '<span class="token attr">$1</span>$2<span class="token attr-value">$3</span>');
          return '<span class="token tag">'+p1+'</span>'+p2+'<span class="token tag">'+p3+'</span>';
        });
      } else if(lang === 'css') {
        code = code.replace(/(\/\*[\s\S]*?\*\/)/g, '<span class="token comment">$1</span>');
        code = code.replace(/([.#]?[a-zA-Z0-9_-]+)(\s*\{)/g, '<span class="token selector">$1</span>$2');
        code = code.replace(/([a-zA-Z-]+)(:)/g, '<span class="token property">$1</span>$2');
        code = code.replace(/("([^"\\]|\\.)*")|('([^'\\]|\\.)*')/g, '<span class="token string">$&</span>');
        code = code.replace(/\b\d+(\.\d+)?(px|em|rem|%)?\b/g, '<span class="token value">$&</span>');
        code = code.replace(/(;|{|})/g, '<span class="token punctuation">$1</span>');
      }
      return code;
    }

    // Update line numbers
    function updateLineNumbers() {
      const lines = editor.value.split('\n').length;
      lineNumbers.innerHTML = Array.from({length:lines},(_,i)=>i+1).join('<br>');
    }

    // Update highlight
    function updateHighlight() {
      let code = editor.value.replace(/\t/g, '    ');
      let html = highlightCode(code, lang);
      // Highlight find matches
      if(findMatches.length) {
        let offset = 0;
        let out = '';
        for(let i=0;i<findMatches.length;i++) {
          let m = findMatches[i];
          let before = html.slice(offset, m.start);
          let match = html.slice(m.start, m.end);
          let cls = 'find-highlight'+(i===findIndex?' current':'');
          out += before + `<span class="${cls}">${match}</span>`;
          offset = m.end;
        }
        out += html.slice(offset);
        html = out;
      }
      highlight.innerHTML = html;
    }

    // Update status bar
    function updateStatus() {
      let pos = editor.selectionStart;
      let lines = editor.value.substr(0,pos).split('\n');
      let line = lines.length;
      let col = lines[lines.length-1].length+1;
      cursorPos.textContent = `Ln ${line}, Col ${col}`;
      let words = (editor.value.match(/\b\w+\b/g)||[]).length;
      wordCount.textContent = `Words: ${words} | Chars: ${editor.value.length}`;
    }

    // Update all
    function updateAll() {
      updateLineNumbers();
      updateHighlight();
      updateStatus();
      localStorage.setItem('notepad-content', editor.value);
      localStorage.setItem('notepad-lang', lang);
      localStorage.setItem('notepad-theme', theme);
      editor.style.fontSize = fontSize.value+'px';
      highlight.style.fontSize = fontSize.value+'px';
    }

    // Theme
    function setTheme() {
      if(theme==='light') document.body.classList.add('light');
      else document.body.classList.remove('light');
    }

    // Find/replace
    function doFind() {
      findMatches = [];
      findIndex = 0;
      let val = editor.value;
      let q = findInput.value;
      if(!q) { updateHighlight(); return; }
      let regex;
      if(regexChk.checked) {
        try { regex = new RegExp(q, 'g'); } catch(e){ return; }
      } else {
        regex = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
      }
      let m;
      while((m=regex.exec(val))!==null) {
        findMatches.push({start:m.index, end:m.index+m[0].length});
        if(m.index===regex.lastIndex) regex.lastIndex++;
      }
      updateHighlight();
      if(findMatches.length) selectFind(findIndex);
    }
    function selectFind(i) {
      if(!findMatches.length) return;
      let m = findMatches[i];
      editor.focus();
      editor.selectionStart = m.start;
      editor.selectionEnd = m.end;
      editor.scrollTop = editor.scrollHeight*(m.start/editor.value.length);
      updateHighlight();
    }
    function findNext() {
      if(!findMatches.length) return;
      findIndex = (findIndex+1)%findMatches.length;
      selectFind(findIndex);
    }
    function findPrev() {
      if(!findMatches.length) return;
      findIndex = (findIndex-1+findMatches.length)%findMatches.length;
      selectFind(findIndex);
    }
    function doReplace() {
      if(!findMatches.length) return;
      let m = findMatches[findIndex];
      let before = editor.value.slice(0,m.start);
      let after = editor.value.slice(m.end);
      let rep = replaceInput.value;
      editor.value = before+rep+after;
      updateAll();
      doFind();
    }
    function doReplaceAll() {
      let q = findInput.value;
      if(!q) return;
      let val = editor.value;
      let rep = replaceInput.value;
      let regex;
      if(regexChk.checked) {
        try { regex = new RegExp(q, 'g'); } catch(e){ return; }
      } else {
        regex = new RegExp(q.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
      }
      editor.value = val.replace(regex, rep);
      updateAll();
      doFind();
    }

    // Auto indent
    editor.addEventListener('keydown', e=>{
      if(e.key==='Tab') {
        e.preventDefault();
        let start = editor.selectionStart, end = editor.selectionEnd;
        editor.value = editor.value.substring(0,start)+'    '+editor.value.substring(end);
        editor.selectionStart = editor.selectionEnd = start+4;
        updateAll();
      } else if(e.key==='Enter') {
        let start = editor.selectionStart;
        let before = editor.value.substring(0,start);
        let m = before.match(/(^|\n)([ \t]*)[^\n]*$/);
        let indent = m?m[2]:'';
        setTimeout(()=>{
          let pos = editor.selectionStart;
          editor.value = editor.value.substring(0,pos)+indent+editor.value.substring(pos);
          editor.selectionStart = editor.selectionEnd = pos+indent.length;
          updateAll();
        },0);
      } else if((e.ctrlKey||e.metaKey)&&e.key==='s') {
        e.preventDefault();
        saveBtn.click();
      }
    });

    // Events
    editor.addEventListener('input', updateAll);
    editor.addEventListener('scroll', ()=>{ highlight.scrollTop = editor.scrollTop; });
    editor.addEventListener('click', updateStatus);
    editor.addEventListener('keyup', updateStatus);

    langSel.addEventListener('change', ()=>{ lang=langSel.value; updateAll(); });
    fontSize.addEventListener('input', ()=>{ updateAll(); });
    themeBtn.addEventListener('click', ()=>{ theme=theme==='dark'?'light':'dark'; setTheme(); updateAll(); });
    openBtn.addEventListener('click', ()=>{ fileInput.click(); });
    fileInput.addEventListener('change', e=>{
      let file = e.target.files[0];
      if(!file) return;
      let reader = new FileReader();
      reader.onload = ev=>{
        editor.value = ev.target.result;
        updateAll();
      };
      reader.readAsText(file);
    });
    saveBtn.addEventListener('click', ()=>{
      let ext = {js:'.js',html:'.html',css:'.css',plain:'.txt'}[lang]||'.txt';
      let blob = new Blob([editor.value],{type:'text/plain'});
      let a = document.createElement('a');
      a.href = URL.createObjectURL(blob);
      a.download = 'note'+ext;
      a.click();
      URL.revokeObjectURL(a.href);
    });
    undoBtn.addEventListener('click', ()=>document.execCommand('undo'));
    redoBtn.addEventListener('click', ()=>document.execCommand('redo'));
    findBtn.addEventListener('click', ()=>{ findBar.style.display='flex'; findInput.focus(); });
    closeFindBtn.addEventListener('click', ()=>{ findBar.style.display='none'; findMatches=[]; updateHighlight(); });
    findInput.addEventListener('input', doFind);
    regexChk.addEventListener('change', doFind);
    findNextBtn.addEventListener('click', findNext);
    findPrevBtn.addEventListener('click', findPrev);
    replaceBtn.addEventListener('click', doReplace);
    replaceAllBtn.addEventListener('click', doReplaceAll);

    // Load state
    editor.value = localStorage.getItem('notepad-content')||'';
    langSel.value = lang;
    fontSize.value = localStorage.getItem('notepad-fontsize')||'16';
    setTheme();
    updateAll();
  </script>
</body>
</html>
```

