import Foundation
import AVFoundation
import Combine

class AudioRecorderViewModel: NSObject, ObservableObject, AVAudioRecorderDelegate {
    @Published var isRecording = false
    @Published var powerLevels: [Float] = Array(repeating: 0, count: 5)

    private var audioRecorder: AVAudioRecorder?
    private var timer: Timer?
    private let numberOfBars = 5

    func requestPermission(completion: @escaping (Bool) -> Void) {
        AVAudioSession.sharedInstance().requestRecordPermission { allowed in
            DispatchQueue.main.async {
                completion(allowed)
            }
        }
    }

    func startRecording() {
        requestPermission { [weak self] allowed in
            guard let self = self, allowed else { return }
            let session = AVAudioSession.sharedInstance()
            do {
                try session.setCategory(.playAndRecord, mode: .default, options: [.defaultToSpeaker])
                try session.setActive(true)
                let url = self.getFileURL()
                let settings: [String: Any] = [
                    AVFormatIDKey: Int(kAudioFormatMPEG4AAC),
                    AVSampleRateKey: 44100,
                    AVNumberOfChannelsKey: 1,
                    AVEncoderAudioQualityKey: AVAudioQuality.high.rawValue
                ]
                self.audioRecorder = try AVAudioRecorder(url: url, settings: settings)
                self.audioRecorder?.delegate = self
                self.audioRecorder?.isMeteringEnabled = true
                self.audioRecorder?.prepareToRecord()
                self.audioRecorder?.record()
                self.isRecording = true
                self.startMetering()
            } catch {
                print("Recording failed: \(error.localizedDescription)")
            }
        }
    }

    func stopRecording() {
        audioRecorder?.stop()
        isRecording = false
        stopMetering()
        do {
            try AVAudioSession.sharedInstance().setActive(false)
        } catch {
            print("Failed to deactivate session: \(error.localizedDescription)")
        }
    }

    private func getFileURL() -> URL {
        let fileName = "recording_\(Date().timeIntervalSince1970).m4a"
        let docs = FileManager.default.urls(for: .documentDirectory, in: .userDomainMask)[0]
        return docs.appendingPathComponent(fileName)
    }

    private func startMetering() {
        timer = Timer.scheduledTimer(withTimeInterval: 0.05, repeats: true) { [weak self] _ in
            guard let self = self, let recorder = self.audioRecorder, recorder.isRecording else { return }
            recorder.updateMeters()
            let basePower = recorder.averagePower(forChannel: 0)
            let normalized = max(0, min(1, (basePower + 60) / 60))
            self.powerLevels = (0..<self.numberOfBars).map { _ in
                Float(normalized * 100) * Float.random(in: 0.7...1.0)
            }
        }
    }

    private func stopMetering() {
        timer?.invalidate()
        timer = nil
        powerLevels = Array(repeating: 0, count: numberOfBars)
    }
}
```

