   struct Node {
       std::array<Node*, 26> children;
       int cnt;
       Node() : cnt(0) {
           children.fill(nullptr);
       }
   };
   ```

2. **Use a map/unordered_map for sparse tries:**  
   If your trie is very sparse (most nodes have few children), you can use `std::unordered_map<char, Node*>` for the children. This saves memory at the cost of slower access.

   ```cpp
   #include <unordered_map>
   struct Node {
       std::unordered_map<char, Node*> children;
       int cnt;
       Node() : cnt(0) {}
   };
   ```

3. **Iterative instead of recursive functions:**  
   Recursion can use extra stack memory. Iterative implementations for `insert` and `queryPrefix` can be more memory efficient.

4. **Advanced: Memory Pooling:**  
   For very large tries, consider using a memory pool to allocate nodes in bulk, reducing per-node allocation overhead and fragmentation.

**Example with fixed-size array and iterative methods:**

```cpp
struct Node {
    Node* children[26];
    int cnt;
    Node() : cnt(0) {
        memset(children, 0, sizeof(children));
    }
};

class Trie {
public:
    Trie() { root = new Node(); }
    void insert(const string& s) {
        Node* cur = root;
        for (char c : s) {
            int idx = c - 'a';
            if (!cur->children[idx]) cur->children[idx] = new Node();
            cur = cur->children[idx];
            cur->cnt++;
        }
    }
    int queryPrefix(const string& s) {
        Node* cur = root;
        int sum = 0;
        for (char c : s) {
            int idx = c - 'a';
            if (!cur->children[idx]) break;
            cur = cur->children[idx];
            sum += cur->cnt;
        }
        return sum;
    }
private:
    Node* root;
};
```

**Summary:**  
- Replace `vector<Node*>` with a fixed-size array or `std::array`.
- Consider `unordered_map` for sparse tries.
