    // Connect all other components to the component with the globally cheapest house
    vector<pair<int, int>> new_roads;
    for (auto& [root, p] : comp_min) {
        if (root == min_root) continue;
        new_roads.emplace_back(min_house, p.second);
    }

    cout << new_roads.size() << "\n";
    for (auto& [u, v] : new_roads) {
        cout << u << " " << v << "\n";
    }
    return 0;
}
