To achieve character movement that aligns with arbitrary surfaces in Unity 2023, you need to:

1. Detect the surface normal beneath the character (using raycasting).
2. Align the character's up vector with the surface normal.
3. Move the character along the tangent plane of the surface.
4. Apply gravity or a "stick to surface" force along the normal.

Here's a basic C# script using a CharacterController (can be adapted for Rigidbody):

```csharp
using UnityEngine;

[RequireComponent(typeof(CharacterController))]
public class SurfaceAlignedMovement : MonoBehaviour
{
    public float moveSpeed = 5f;
    public float gravity = 9.81f;
    public float raycastDistance = 2f;
    private CharacterController controller;
    private Vector3 velocity;

    void Start()
    {
        controller = GetComponent<CharacterController>();
    }

    void Update()
    {
        // 1. Raycast down to find the surface normal
        if (Physics.Raycast(transform.position, -transform.up, out RaycastHit hit, raycastDistance))
        {
            Vector3 normal = hit.normal;

            // 2. Align character's up with surface normal
            Quaternion toNormal = Quaternion.FromToRotation(transform.up, normal) * transform.rotation;
            transform.rotation = Quaternion.Slerp(transform.rotation, toNormal, Time.deltaTime * 10f);

            // 3. Get input and project movement onto surface
            Vector3 input = new Vector3(Input.GetAxis("Horizontal"), 0, Input.GetAxis("Vertical"));
            Vector3 right = Vector3.Cross(transform.up, transform.forward).normalized;
            Vector3 forward = Vector3.Cross(right, transform.up).normalized;
            Vector3 move = (forward * input.z + right * input.x).normalized * moveSpeed;

            // 4. Apply gravity along the surface normal
            if (controller.isGrounded)
                velocity = Vector3.zero;
            else
                velocity += -normal * gravity * Time.deltaTime;

            controller.Move((move + velocity) * Time.deltaTime);
        }
        else
        {
            // Fallback: apply default gravity if not grounded
            velocity += Physics.gravity * Time.deltaTime;
            controller.Move(velocity * Time.deltaTime);
        }
    }
}
```

