<head>
  <meta charset="UTF-8">
  <title>Simple OS Emulator</title>
  <style>
    html, body {
      margin: 0; padding: 0;
      width: 100vw; height: 100vh;
      font-family: sans-serif;
      background: linear-gradient(135deg, #1e3c72, #2a5298);
      overflow: hidden;
    }
    #desktop {
      position: absolute;
      top: 0; left: 0; right: 0; bottom: 40px;
      padding: 10px;
      display: flex;
      flex-wrap: wrap;
      align-content: flex-start;
      gap: 12px;
    }
    .desktop-icon {
      width: 80px;
      text-align: center;
      color: white;
      cursor: pointer;
      user-select: none;
    }
    .desktop-icon img {
      width: 48px; height: 48px;
      margin-bottom: 4px;
    }
    .desktop-icon:hover {
      background: rgba(255,255,255,0.1);
      border-radius: 8px;
    }
    #taskbar {
      position: absolute;
      left: 0; right: 0; bottom: 0;
      height: 40px;
      background: #222a3a;
      display: flex;
      align-items: center;
      padding: 0 10px;
      color: white;
      z-index: 1000;
    }
    #start-btn {
      width: 80px;
      height: 30px;
      background: #3a4688;
      border-radius: 4px;
      border: none;
      color: white;
      font-weight: bold;
      cursor: pointer;
      margin-right: 10px;
    }
    #start-btn:hover {
      background: #5268b0;
    }
    #start-menu {
      position: absolute;
      left: 10px; bottom: 50px;
      width: 160px;
      background: #2b3360;
      border-radius: 8px 8px 8px 0;
      box-shadow: 0 6px 15px rgba(0,0,0,0.5);
      color: #ddd;
      display: none;
      flex-direction: column;
      padding: 8px 0;
      z-index: 1100;
    }
    #start-menu button {
      background: none;
      border: none;
      color: #ddd;
      text-align: left;
      font-size: 14px;
      padding: 8px 20px;
      cursor: pointer;
      width: 100%;
    }
    #start-menu button:hover {
      background: #465690;
    }
    .window {
      position: absolute;
      background: #fff;
      border-radius: 6px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.4);
      min-width: 300px;
      min-height: 180px;
      overflow: hidden;
      display: flex;
      flex-direction: column;
      z-index: 200;
    }
    .window .titlebar {
      background: linear-gradient(to right, #4a67b2, #6b83cc);
      color: white;
      padding: 6px 12px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      cursor: grab;
      user-select: none;
    }
    .window .titlebar .window-controls button {
      width: 26px; height: 22px;
      background: none;
      border: none;
      color: white;
      font-weight: bold;
      cursor: pointer;
      border-radius: 4px;
      margin-left: 4px;
    }
    .window .titlebar .window-controls button:hover {
      background: rgba(255,255,255,0.2);
    }
    .window .content {
      flex: 1;
      background: #fff;
      overflow: auto;
      padding: 12px;
    }
    .file-explorer .toolbar button {
      margin-right: 8px;
    }
    .file-list ul {
      list-style: none;
      margin: 0; padding: 0;
    }
    .file-list li {
      padding: 6px 12px;
      border-bottom: 1px solid #ddd;
      cursor: pointer;
    }
    .file-list li.selected {
      background: #4a67b2;
      color: white;
    }
    .file-list li:hover:not(.selected) {
      background: #d0d6f5;
    }
    .text-editor textarea {
      width: 100%; height: 200px;
      font-family: monospace;
      font-size: 14px;
      border-radius: 4px;
      border: 1px solid #ccc;
      padding: 8px;
      resize: none;
    }
  </style>
</head>
<body>
  <div id="desktop"></div>
  <div id="taskbar">
    <button id="start-btn">Start</button>
  </div>
  <div id="start-menu">
    <button data-app="explorer">File Explorer</button>
    <button data-app="editor">Text Editor</button>
  </div>
  <div id="windows"></div>
  <script>
    // In-memory file system
    let fileSystem = {
      "Readme.txt": "Welcome to the Simple OS Emulator.\nYou can create and edit text files here.",
      "Notes.txt": "These are some sample notes."
    };

    // Desktop icons
    const desktopApps = [
      {name: 'File Explorer', icon: '📁', appId:'explorer'},
      {name: 'Text Editor', icon: '📝', appId:'editor'}
    ];

    // Render desktop icons
    function renderDesktopIcons() {
      const desktop = document.getElementById('desktop');
      desktop.innerHTML = '';
      desktopApps.forEach((app, i) => {
        const icon = document.createElement('div');
        icon.className = 'desktop-icon';
        icon.title = app.name;
        icon.style.marginTop = (i*100) + 'px';
        icon.innerHTML = `<div style="font-size:48px;">${app.icon}</div><div>${app.name}</div>`;
        icon.onclick = () => openApp(app.appId);
        desktop.appendChild(icon);
      });
    }

    // Window management
    let zIndexCounter = 100;
    function bringToFront(win) {
      zIndexCounter++;
      win.style.zIndex = zIndexCounter;
    }

    function createWindow(title, contentEl, options={}) {
      const win = document.createElement('div');
      win.className = 'window';
      win.style.top = options.top || '80px';
      win.style.left = options.left || '80px';
      win.style.width = options.width || '400px';
      win.style.height = options.height || '300px';

      const titlebar = document.createElement('div');
      titlebar.className = 'titlebar';
      titlebar.innerHTML = `<span>${title}</span>`;
      const controls = document.createElement('span');
      controls.className = 'window-controls';
      controls.innerHTML = `
        <button title="Close">&times;</button>
      `;
      titlebar.appendChild(controls);

      // Dragging
      let isDragging = false, dragStartX, dragStartY, winStartX, winStartY;
      titlebar.addEventListener('mousedown', e => {
        if(e.target.tagName === 'BUTTON') return;
        isDragging = true;
        dragStartX = e.clientX;
        dragStartY = e.clientY;
        winStartX = win.offsetLeft;
        winStartY = win.offsetTop;
        bringToFront(win);
      });
      document.addEventListener('mousemove', e => {
        if(!isDragging) return;
        let newX = winStartX + (e.clientX - dragStartX);
        let newY = winStartY + (e.clientY - dragStartY);
        newX = Math.max(0, Math.min(window.innerWidth - win.offsetWidth, newX));
        newY = Math.max(0, Math.min(window.innerHeight - 40 - win.offsetHeight, newY));
        win.style.left = newX + 'px';
        win.style.top = newY + 'px';
      });
      document.addEventListener('mouseup', () => isDragging = false);

      controls.querySelector('button').onclick = () => win.remove();

      win.appendChild(titlebar);
      const content = document.createElement('div');
      content.className = 'content';
      content.appendChild(contentEl);
      win.appendChild(content);

      win.addEventListener('mousedown', () => bringToFront(win));
      document.getElementById('windows').appendChild(win);
      bringToFront(win);
      return win;
    }

    // File Explorer App
    function createFileExplorerApp() {
      const container = document.createElement('div');
      container.className = 'file-explorer';
      const toolbar = document.createElement('div');
      toolbar.className = 'toolbar';
      const btnNew = document.createElement('button');
      btnNew.textContent = 'New File';
      const btnRename = document.createElement('button');
      btnRename.textContent = 'Rename';
      btnRename.disabled = true;
      const btnDelete = document.createElement('button');
      btnDelete.textContent = 'Delete';
      btnDelete.disabled = true;
      toolbar.append(btnNew, btnRename, btnDelete);
      container.appendChild(toolbar);

      const fileList = document.createElement('div');
      fileList.className = 'file-list';
      const ul = document.createElement('ul');
      fileList.appendChild(ul);
      container.appendChild(fileList);

      let selectedFile = null;

      function refreshList() {
        ul.innerHTML = '';
        Object.keys(fileSystem).forEach(fname => {
          const li = document.createElement('li');
          li.textContent = fname;
          li.onclick = () => {
            [...ul.children].forEach(l => l.classList.remove('selected'));
            li.classList.add('selected');
            selectedFile = fname;
            btnRename.disabled = false;
            btnDelete.disabled = false;
          };
          li.ondblclick = () => openTextEditor(fname);
          ul.appendChild(li);
        });
        btnRename.disabled = true;
        btnDelete.disabled = true;
        selectedFile = null;
      }

      btnNew.onclick = () => {
        let fname = prompt('Enter new file name:', 'Untitled.txt');
        if(fname && !fileSystem[fname]) {
          fileSystem[fname] = '';
          refreshList();
        } else if(fileSystem[fname]) {
          alert('File already exists!');
        }
      };
      btnRename.onclick = () => {
        if(!selectedFile) return;
        let fname = prompt('Rename file:', selectedFile);
        if(fname && fname !== selectedFile && !fileSystem[fname]) {
          fileSystem[fname] = fileSystem[selectedFile];
          delete fileSystem[selectedFile];
          refreshList();
        } else if(fileSystem[fname]) {
          alert('File already exists!');
        }
      };
      btnDelete.onclick = () => {
        if(selectedFile && confirm('Delete file "'+selectedFile+'"?')) {
          delete fileSystem[selectedFile];
          refreshList();
        }
      };

      refreshList();
      return container;
    }

    // Text Editor App
    function createTextEditorApp(filename) {
      const container = document.createElement('div');
      container.className = 'text-editor';
      const toolbar = document.createElement('div');
      const btnSave = document.createElement('button');
      btnSave.textContent = 'Save';
      toolbar.appendChild(btnSave);
      container.appendChild(toolbar);
      const textarea = document.createElement('textarea');
      textarea.value = filename && fileSystem[filename] !== undefined ? fileSystem[filename] : '';
      container.appendChild(textarea);

      btnSave.onclick = () => {
        if(filename) {
          fileSystem[filename] = textarea.value;
          alert('Saved!');
        } else {
          let fname = prompt('Save as:', 'Untitled.txt');
          if(fname) {
            fileSystem[fname] = textarea.value;
            alert('Saved!');
          }
        }
      };
      return container;
    }

    function openApp(appId) {
      if(appId === 'explorer') {
        createWindow('File Explorer', createFileExplorerApp());
      } else if(appId === 'editor') {
        createWindow('Text Editor', createTextEditorApp());
      }
    }
    function openTextEditor(fname) {
      createWindow('Text Editor - ' + fname, createTextEditorApp(fname));
    }

    // Start menu
    document.getElementById('start-btn').onclick = e => {
      e.stopPropagation();
      const menu = document.getElementById('start-menu');
      menu.style.display = menu.style.display === 'flex' ? 'none' : 'flex';
    };
    document.body.onclick = () => document.getElementById('start-menu').style.display = 'none';
    document.querySelectorAll('#start-menu button').forEach(btn => {
      btn.onclick = () => {
        openApp(btn.dataset.app);
        document.getElementById('start-menu').style.display = 'none';
      };
    });

    renderDesktopIcons();
  </script>
</body>
</html>
```

**How to use:**
- Open the HTML file in your browser.
- Click desktop icons or Start menu to open apps.
- Drag windows by their title bars.
