- When receiving a UDP packet, interpret the buffer as an array of these structs.
- For each pair, check that `event_index` is valid, then emit the event using `libevdev_uinput_write_event`.
- After all events, send a `SYN_REPORT`.

**Example C snippet:**
```c
#include <stdint.h>
#define EVENT_COUNT (sizeof(REGISTERED_EVENTS) / sizeof(REGISTERED_EVENTS[0]))

struct event_pair {
    int16_t event_index;
    int16_t event_value;
};

while (1) {
    ssize_t n = recvfrom(sockfd, buffer, sizeof(buffer), 0, (struct sockaddr *) &cli_addr, &cli_len);
    if (n < 0) { perror("recvfrom"); continue; }
    if (n % sizeof(struct event_pair) != 0) {
        fprintf(stderr, "Malformed packet\n");
        continue;
    }
    int pair_count = n / sizeof(struct event_pair);
    struct event_pair *pairs = (struct event_pair *)buffer;
    for (int i = 0; i < pair_count; ++i) {
        int idx = pairs[i].event_index;
        int val = pairs[i].event_value;
        if (idx >= 0 && idx < EVENT_COUNT) {
            libevdev_uinput_write_event(controller, REGISTERED_EVENTS[idx].type, REGISTERED_EVENTS[idx].code, val);
        }
    }
    libevdev_uinput_write_event(controller, EV_SYN, SYN_REPORT, 0);
}
```

