**Prompt Recap:**  
Write code for a geometry shader in Unity that samples a texture with transparency:
1. Create a quad for each pixel that is not transparent.
2. Extrude each quad by a factor.

---

**My Answer:**

To achieve this in Unity, you need a geometry shader that:
- Receives a mesh of points, each with a UV corresponding to a texel in your texture.
- In the geometry shader, samples the texture at the UV.
- If the alpha is above a threshold, emits a quad (two triangles) at that position, extruded along a direction by a factor.

**Shader Code Example:**

```hlsl
Shader "Custom/ExtrudedTextureQuads"
{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrude Factor", Float) = 0.1
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.1
    }
    SubShader
    {
        Tags { "RenderType"="Opaque" }
        Pass
        {
            CGPROGRAM
            #pragma vertex vert
            #pragma geometry geom
            #pragma fragment frag
            #pragma target 4.0

            #include "UnityCG.cginc"

            sampler2D _MainTex;
            float _Extrude;
            float _AlphaThreshold;
            float4 _MainTex_TexelSize;

            struct appdata
            {
                float3 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct v2g
            {
                float4 vertex : POSITION;
                float2 uv : TEXCOORD0;
            };

            struct g2f
            {
                float4 vertex : SV_POSITION;
                float2 uv : TEXCOORD0;
            };

            v2g vert(appdata v)
            {
                v2g o;
                o.vertex = UnityObjectToClipPos(float4(v.vertex, 1.0));
                o.uv = v.uv;
                return o;
            }

            [maxvertexcount(6)]
            void geom(point v2g IN[1], inout TriangleStream<g2f> triStream)
            {
                float4 col = tex2D(_MainTex, IN[0].uv);
                if (col.a < _AlphaThreshold)
                    return;

                // Calculate quad size based on texel size
                float2 texel = _MainTex_TexelSize.xy;
                float4 basePos = IN[0].vertex;

                // Offsets for quad corners in object space
                float3 offsets[4] = {
                    float3(-texel.x, -texel.y, 0),
                    float3( texel.x, -texel.y, 0),
                    float3( texel.x,  texel.y, _Extrude),
                    float3(-texel.x,  texel.y, _Extrude)
                };

                g2f o;

                // First triangle
                o.vertex = UnityObjectToClipPos(float4(IN[0].vertex.xyz + offsets[0], 1.0));
                o.uv = IN[0].uv;
                triStream.Append(o);

