{
    Properties
    {
        _MainTex ("Texture", 2D) = "white" {}
        _Extrude ("Extrude Factor", Float) = 0.1
        _AlphaThreshold ("Alpha Threshold", Range(0,1)) = 0.01
    }
    SubShader
    {
