void CreatePointMesh(Texture2D tex, float quadWorldSize)
{
    int w = tex.width, h = tex.height;
    Vector3[] vertices = new Vector3[w * h];
    Vector2[] uvs = new Vector2[w * h];
    int[] indices = new int[w * h];

    for (int y = 0; y < h; y++)
    {
        for (int x = 0; x < w; x++)
        {
            int i = y * w + x;
            vertices[i] = new Vector3(x * quadWorldSize, y * quadWorldSize, 0);
            uvs[i] = new Vector2((float)x / w, (float)y / h);
            indices[i] = i;
        }
    }

    Mesh mesh = new Mesh();
    mesh.vertices = vertices;
    mesh.uv = uvs;
    mesh.SetIndices(indices, MeshTopology.Points, 0);
    GetComponent<MeshFilter>().mesh = mesh;
}
