class XDetails extends HTMLElement {
  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
    this._expanded = false;
    this.shadowRoot.innerHTML = `
      <style>
        :host {
          display: block;
          font-family: sans-serif;
        }
        .header {
          display: flex;
          align-items: center;
          font-size: 1.2em;
          border-bottom: 1px solid #bbb;
          padding-bottom: 4px;
          margin-bottom: 6px;
          cursor: pointer;
          user-select: none;
        }
        .indicator {
          width: 20px;
          height: 20px;
          border: 1px solid #333;
          display: flex;
          align-items: center;
          justify-content: center;
          margin-right: 8px;
          font-weight: bold;
          font-size: 1em;
        }
        .intro {
          margin: 8px 0;
        }
        .details {
          margin: 8px 0;
          display: none;
        }
        .details[expanded] {
          display: block;
        }
        .expand-btn {
          margin-top: 8px;
          background: none;
          border: 1px solid #888;
          border-radius: 3px;
          padding: 4px 10px;
          cursor: pointer;
        }
      </style>
      <div class="header" tabindex="0" aria-expanded="false">
        <span class="indicator">+</span>
        <slot name="header"></slot>
      </div>
      <div class="intro">
        <slot name="intro"></slot>
      </div>
      <div class="details">
        <slot name="details"></slot>
      </div>
      <button class="expand-btn">expand more</button>
    `;
  }

  connectedCallback() {
    this._header = this.shadowRoot.querySelector('.header');
    this._indicator = this.shadowRoot.querySelector('.indicator');
    this._details = this.shadowRoot.querySelector('.details');
    this._expandBtn = this.shadowRoot.querySelector('.expand-btn');

    this._header.addEventListener('click', () => this.toggle());
    this._header.addEventListener('keydown', e => {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        this.toggle();
      }
    });
    this._expandBtn.addEventListener('click', () => this.expand());

    this._update();
  }

  toggle() {
    this._expanded = !this._expanded;
    this._update();
  }

  expand() {
    this._expanded = true;
    this._update();
  }

  _update() {
    if (this._expanded) {
      this._indicator.textContent = '−';
      this._details.setAttribute('expanded', '');
      this._header.setAttribute('aria-expanded', 'true');
      this._details.style.display = 'block';
      this._expandBtn.style.display = 'none';
    } else {
      this._indicator.textContent = '+';
      this._details.removeAttribute('expanded');
      this._header.setAttribute('aria-expanded', 'false');
      this._details.style.display = 'none';
      this._expandBtn.style.display = 'inline-block';
    }
  }
}

customElements.define('x-details', XDetails);
```

