To refactor the Playwright end-to-end test for user CRUD operations according to SOLID principles and best practices, we should:

- Encapsulate API logic in a dedicated service class (Single Responsibility Principle).
- Use the Page Object Model for UI interactions.
- Keep the test spec focused on orchestration and assertions.
- Use dependency injection for easier testing and mocking.
- Optionally, use the Facade or Builder pattern to abstract complex flows.

**Example Implementation in TypeScript:**

```typescript
// userService.ts
import { APIRequestContext } from '@playwright/test';

export interface CreateUserPayload {
  username: string;
  email: string;
  password: string;
  // ...other fields
}

export interface PermissionPayload {
  permissions: string[];
  // ...other fields
}

export interface UserCredentials {
  username: string;
  password: string;
}

export class UserService {
  constructor(private readonly request: APIRequestContext) {}

  async createUser(payload: CreateUserPayload): Promise<{ id: string }> {
    const res = await this.request.post('/users/v2/create', { data: payload });
    if (res.status() !== 201) throw new Error('User creation failed');
    return await res.json();
  }

  async updatePermissions(userId: string, payload: PermissionPayload): Promise<UserCredentials> {
    const res = await this.request.post('/users/v2/permissions', { data: { ...payload, id: userId } });
    if (res.status() !== 200) throw new Error('Permission update failed');
    return await res.json();
  }

  async createAdminUser(createPayload: CreateUserPayload, permissionPayload: PermissionPayload): Promise<UserCredentials> {
    const { id } = await this.createUser(createPayload);
    return await this.updatePermissions(id, permissionPayload);
  }
}

