**Approach:**
1. Collect all y1 and y2, sort and deduplicate to discretize y-coordinates.
2. For each rectangle, create two events: entering (x1, y1, y2, +1) and leaving (x2, y1, y2, -1).
3. Sort all events by x.
4. Use a segment tree to maintain the total covered length on the y-axis.
5. As you process events in x order, for each event, compute the area covered since the previous x (dx * covered_y_length), and update the segment tree for the current event's y-interval.
6. Output the total area modulo 1e9+7.

**C++ code:**
```cpp
#include <iostream>
#include <vector>
#include <algorithm>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    ll x;
    int y1, y2;
    int type;
    Event(ll x, int y1, int y2, int type): x(x), y1(y1), y2(y2), type(type) {}
    bool operator<(const Event& e) const { return x < e.x; }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<ll> ys;
    SegmentTree(const vector<ll>& ys): ys(ys) {
        n = ys.size() - 1;
        cnt.assign(4*n, 0);
        len.assign(4*n, 0);
    }
    void update(int idx, int l, int r, int ql, int qr, int val) {
        if (qr <= l || ql >= r) return;
        if (ql <= l && r <= qr) {
            cnt[idx] += val;
        } else {
            int m = (l+r)/2;
            update(idx*2, l, m, ql, qr, val);
            update(idx*2+1, m, r, ql, qr, val);
        }
        if (cnt[idx] > 0) len[idx] = ys[r] - ys[l];
        else if (r - l == 1) len[idx] = 0;
        else len[idx] = len[idx*2] + len[idx*2+1];
    }
};

int main() {
    int n;
    cin >> n;
    vector<vector<ll>> rects(n, vector<ll>(4));
    vector<ll> ys;
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
