This is a classic problem of calculating the union area of axis-aligned rectangles, where rectangles may overlap and the total area should only count each region once. Given the constraints (n ≤ 50, coordinates up to 1e9), the standard and efficient approach is to use a sweep line (scanning line) algorithm with segment tree and y-coordinate discretization.

**Solution outline:**
1. For each rectangle, create two events: one for the left edge (entering) and one for the right edge (leaving).
2. Collect all y1 and y2, sort and deduplicate to discretize y-coordinates.
3. For each event, update the segment tree to reflect the current coverage on the y-axis.
4. As we process events in order of x, for each interval between events, multiply the width (delta x) by the current covered y-length (from the segment tree) and accumulate.
5. Output the result modulo 1e9+7.

**C++ code:**
```cpp
#include <bits/stdc++.h>
using namespace std;
typedef long long ll;
const int MOD = 1e9+7;

struct Event {
    ll x;
    int y1, y2;
    int type; // +1 for entering, -1 for leaving
    Event(ll x, int y1, int y2, int type): x(x), y1(y1), y2(y2), type(type) {}
    bool operator<(const Event& other) const { return x < other.x; }
};

struct SegmentTree {
    int n;
    vector<int> cnt;
    vector<ll> len;
    vector<ll> ys;
    SegmentTree(const vector<ll>& ys): ys(ys) {
        n = ys.size() - 1;
        cnt.assign(4*n, 0);
        len.assign(4*n, 0);
    }
    void update(int idx, int l, int r, int ql, int qr, int val) {
        if (ql >= r || qr <= l) return;
        if (ql <= l && r <= qr) {
            cnt[idx] += val;
        } else {
            int m = (l + r) / 2;
            update(idx*2, l, m, ql, qr, val);
            update(idx*2+1, m, r, ql, qr, val);
        }
        if (cnt[idx] > 0) len[idx] = ys[r] - ys[l];
        else if (r - l == 1) len[idx] = 0;
        else len[idx] = len[idx*2] + len[idx*2+1];
    }
};

int main() {
    int n;
    cin >> n;
    vector<array<ll,4>> rects(n);
    vector<ll> ys;
    vector<Event> events;
    for (int i = 0; i < n; ++i) {
        cin >> rects[i][0] >> rects[i][1] >> rects[i][2] >> rects[i][3];
        ys.push_back(rects[i][1]);
        ys.push_back(rects[i][3]);
    }
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());
    for (int i = 0; i < n; ++i) {
        int y1 = lower_bound(ys.begin(), ys.end(), rects[i][1]) - ys.begin();
        int y2 = lower_bound(ys.begin(), ys.end(), rects[i][3]) - ys.begin();
        events.emplace_back(rects[i][0], y1, y2, 1);
        events.emplace_back(rects[i][2], y1, y2, -1);
    }
    sort(events.begin(), events.end());
    SegmentTree seg(ys);
    ll ans = 0;
    ll prev_x = events[0].x;
    for (auto& e : events) {
        ll dx = e.x - prev_x;
        ans = (ans + dx % MOD * seg.len[1] % MOD) % MOD;
        seg.update(1, 0, seg.n, e.y1, e.y2, e.type);
        prev_x = e.x;
    }
    cout << ans << endl;
    return 0;
}
```

**Key points:**
