```c
#include <stdio.h>

// Hàm Euclide mở rộng: tìm d = gcd(a, b) và các hệ số x, y sao cho a*x + b*y = d
void extendedEuclid(int a, int b, int *d, int *x, int *y) {
    int x2 = 1, x1 = 0;
    int y2 = 0, y1 = 1;
    int q, r, x_temp, y_temp;

    if (b == 0) {
        *d = a;
        *x = 1;
        *y = 0;
        return;
    }

    while (b > 0) {
        q = a / b;
        r = a - q * b;
        x_temp = x2 - q * x1;
        y_temp = y2 - q * y1;

        a = b;
        b = r;
        x2 = x1;
        x1 = x_temp;
        y2 = y1;
        y1 = y_temp;
    }

    *d = a;
    *x = x2;
    *y = y2;
}

int main() {
    int a, b, d, x, y;
    printf("Nhập a và b: ");
    scanf("%d %d", &a, &b);

    extendedEuclid(a, b, &d, &x, &y);

    printf("gcd(%d, %d) = %d\n", a, b, d);
    printf("Các hệ số x, y sao cho %d*x + %d*y = %d là: x = %d, y = %d\n", a, b, d, x, y);

    return 0;
}
```

