// Hàm Euclide mở rộng: tìm d = gcd(a, b) và các hệ số x, y sao cho ax + by = d
void extendedEuclid(int a, int b, int *d, int *x, int *y) {
    int X2 = 1, X1 = 0;
    int Y2 = 0, Y1 = 1;
    int q, r, X, Y;
    int aa = a, bb = b; // Lưu lại giá trị gốc nếu cần in ra

